import * as THREE from 'three';

/**
 * Fixed shape constants (exported so tests can compute expected dimensions).
 *
 * EAVE_HEIGHT  : height of each pyramidal eave (ConeGeometry height).
 * SPIRE_HEIGHT : height of the spire cylinder crowning the top tier.
 * SPIRE_RADIUS : radius of the spire cylinder.
 */
export const EAVE_HEIGHT = 1.2;
export const SPIRE_HEIGHT = 1.5;
export const SPIRE_RADIUS = 0.12;

/** Vertical pitch of one tier: box body + its eave. */
export const TIER_PITCH = /* documented via buildPagoda */ null;

/**
 * Build a pagoda as a THREE.Group.
 *
 * Documented scene-graph structure (child count is contractual):
 *   Group
 *   ├── Mesh "tier-box-0"   BoxGeometry(w0, tierHeight, w0)
 *   ├── Mesh "tier-eave-0"  ConeGeometry(r0, EAVE_HEIGHT, 4), rotation.y = PI/4
 *   ├── ...
 *   ├── Mesh "tier-box-{tiers-1}"
 *   ├── Mesh "tier-eave-{tiers-1}"
 *   └── Mesh "spire"        CylinderGeometry(SPIRE_RADIUS, SPIRE_RADIUS, SPIRE_HEIGHT)
 *
 * => group.children.length === tiers * 2 + 1
 *
 * Tier i sits on top of tiers 0..i-1, so its base y-offset is
 * i * (tierHeight + EAVE_HEIGHT) and the whole structure's total
 * Box3 height is tiers * (tierHeight + EAVE_HEIGHT) + SPIRE_HEIGHT.
 *
 * ---------------------------------------------------------------------------
 * Eave radius math (inscribed vs circumscribed square) — IMPORTANT:
 *
 * ConeGeometry(radius, height, 4) generates a pyramid whose horizontal
 * cross-section is a square with its four CORNERS on the circle of the given
 * `radius` — i.e. `radius` is the CIRCUMRADIUS of that square, and with the
 * default thetaStart the square's vertices lie on the x/z axes (a "diamond").
 * Rotating by PI/4 about Y makes the square axis-aligned.
 *
 * For a square with circumradius R:
 *     side length s = R * sqrt(2)      (s = R / cos(45°))
 * hence R = s / sqrt(2).
 *
 * We want the eave's footprint side to overhang its tier by eaveOverhang on
 * every side:  s = tierWidth + 2 * eaveOverhang,
 * therefore    radius = (tierWidth + 2 * eaveOverhang) / Math.SQRT2.
 * ---------------------------------------------------------------------------
 */
export function buildPagoda({
  tiers = 5,
  baseWidth = 10,
  tierRatio = 0.82,
  tierHeight = 2.4,
  eaveOverhang = 0.35,
} = {}) {
  if (!Number.isInteger(tiers) || tiers < 1) {
    throw new RangeError(`tiers must be a positive integer, got ${tiers}`);
  }

  const group = new THREE.Group();
  const pitch = tierHeight + EAVE_HEIGHT;

  for (let i = 0; i < tiers; i++) {
    const width = baseWidth * Math.pow(tierRatio, i);
    const tierBaseY = i * pitch;

    // Tier body: square box.
    const box = new THREE.Mesh(new THREE.BoxGeometry(width, tierHeight, width));
    box.name = `tier-box-${i}`;
    box.position.y = tierBaseY + tierHeight / 2;
    group.add(box);

    // Pyramidal eave: see radius derivation above.
    const footprintSide = width + 2 * eaveOverhang;
    const radius = footprintSide / Math.SQRT2; // circumradius of the square
    const eave = new THREE.Mesh(
      new THREE.ConeGeometry(radius, EAVE_HEIGHT, 4)
    );
    eave.name = `tier-eave-${i}`;
    eave.rotation.y = Math.PI / 4; // align the diamond to an axis-aligned square
    eave.position.y = tierBaseY + tierHeight + EAVE_HEIGHT / 2; // base rests on the box top
    group.add(eave);
  }

  // Spire crowning the top eave.
  const spire = new THREE.Mesh(
    new THREE.CylinderGeometry(SPIRE_RADIUS, SPIRE_RADIUS, SPIRE_HEIGHT, 12)
  );
  spire.name = 'spire';
  spire.position.y = tiers * pitch + SPIRE_HEIGHT / 2;
  group.add(spire);

  return group;
}

/**
 * Width of tier i's box, read from the built mesh's geometry parameters
 * (not recomputed from formulas).
 */
export function tierWidth(pagoda, i) {
  const box = pagoda.getObjectByName(`tier-box-${i}`);
  if (!box) throw new RangeError(`no tier box at index ${i}`);
  return box.geometry.parameters.width;
}

/** Circumradius of tier i's eave cone, read from the built mesh geometry. */
export function eaveRadius(pagoda, i) {
  const eave = pagoda.getObjectByName(`tier-eave-${i}`);
  if (!eave) throw new RangeError(`no tier eave at index ${i}`);
  return eave.geometry.parameters.radius;
}

