import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import {
  buildPagoda,
  tierWidth,
  eaveRadius,
  EAVE_HEIGHT,
  SPIRE_HEIGHT,
} from '../src/pagoda.js';

const PARAMS = {
  tiers: 5,
  baseWidth: 10,
  tierRatio: 0.82,
  tierHeight: 2.4,
  eaveOverhang: 0.35,
};

describe('buildPagoda', () => {
  const pagoda = buildPagoda(PARAMS);

  it('exposes consecutive tier widths in exact tierRatio proportion (1e-9)', () => {
    for (let i = 0; i < PARAMS.tiers - 1; i++) {
      const ratio = tierWidth(pagoda, i + 1) / tierWidth(pagoda, i);
      expect(ratio).toBeCloseTo(PARAMS.tierRatio, { precision: 9 });
    }
  });

  it('gives each eave a square footprint of tierWidth + 2*eaveOverhang (1e-6)', () => {
    /*
     * Radius math (inscribed vs circumscribed square):
     *
     * ConeGeometry(r, h, 4) makes a pyramid whose square cross-section has its
     * CORNERS on the circle of radius r — r is the square's CIRCUMRADIUS.
     * For a square with circumradius r, side s = r * sqrt(2), so
     * r = s / sqrt(2). We need side s = tierWidth + 2*eaveOverhang, which is
     * exactly how buildPagoda picks the radius.
     *
     * We verify two independent ways:
     *   1. geometry parameter round-trip: radius * sqrt(2) === expected side;
     *   2. the world-space axis-aligned Box3 of the rotated cone (rotation.y =
     *      PI/4 aligns the diamond to the axes), whose x/z extents equal the
     *      footprint side.
     */
    for (let i = 0; i < PARAMS.tiers; i++) {
      const expectedSide = tierWidth(pagoda, i) + 2 * PARAMS.eaveOverhang;

      // 1. circumradius -> inscribed square side
      const sideFromRadius = eaveRadius(pagoda, i) * Math.SQRT2;
      expect(sideFromRadius).toBeCloseTo(expectedSide, { precision: 6 });

      // 2. world-space bounding box of the axis-aligned rotated cone
      const eave = pagoda.getObjectByName(`tier-eave-${i}`);
      eave.updateWorldMatrix(true, false);
      const bbox = new THREE.Box3().setFromObject(eave);
      const size = new THREE.Vector3();
      bbox.getSize(size);
      expect(size.x).toBeCloseTo(expectedSide, { precision: 6 });
      expect(size.z).toBeCloseTo(expectedSide, { precision: 6 });
    }
  });

  it('has total Box3 height tiers*(tierHeight + EAVE_HEIGHT) + SPIRE_HEIGHT (1e-6)', () => {
    pagoda.updateWorldMatrix(true, true);
    const bbox = new THREE.Box3().setFromObject(pagoda);
    const size = new THREE.Vector3();
    bbox.getSize(size);

    const expected =
      PARAMS.tiers * (PARAMS.tierHeight + EAVE_HEIGHT) + SPIRE_HEIGHT;

    expect(size.y).toBeCloseTo(expected, { precision: 6 });
  });

  it('follows the documented structure: tiers*2 meshes plus one spire', () => {
    // Group children: [box-0, eave-0, box-1, eave-1, ..., box-n, eave-n, spire]
    expect(pagoda.children.length).toBe(PARAMS.tiers * 2 + 1);

    for (let i = 0; i < PARAMS.tiers; i++) {
      expect(pagoda.getObjectByName(`tier-box-${i}`)).toBeInstanceOf(THREE.Mesh);
      expect(pagoda.getObjectByName(`tier-eave-${i}`)).toBeInstanceOf(
        THREE.Mesh
      );
    }
    expect(pagoda.getObjectByName('spire')).toBeInstanceOf(THREE.Mesh);
  });

  it('rejects non-positive or non-integer tier counts', () => {
    expect(() => buildPagoda({ tiers: 0 })).toThrow(RangeError);
    expect(() => buildPagoda({ tiers: 2.5 })).toThrow(RangeError);
  });
});

